  border: 2px solid darkgray;
  border-radius: 4px;
}

.button:focus-visible {
  /* 当支持 :focus-visible 时，画出焦点 */
  outline: 3px solid deepskyblue;
  outline-offset: 3px;
}

@supports not selector(:focus-visible) {
  .button.with-fallback:focus {
    /* 对于不支持 :focus-visible 的浏览器的回落 */
    outline: 3px solid deepskyblue;
    outline-offset: 3px;
  }
}

